svg.script:
let games=[];

let currentCategory="All";



const gamesURL=

"https://raw.githubusercontent.com/CowGoMoo357/htmlgamesrepos/main/games.json";





async function loadGames(){


try{


const response =
await fetch(
gamesURL + "?t=" + Date.now()
);



if(!response.ok){

throw new Error(
"HTTP " + response.status
);

}



const data =
await response.json();



console.log(data);



games =
data.games || [];



renderGames();



}

catch(error){


document.getElementById("games")
.innerHTML=

`

<div class="card">

<h2>
Error Loading Games
</h2>

<p>
${error}
</p>

</div>

`;

}


}







function renderGames(){


const box =
document.getElementById("games");


box.innerHTML="";



let list =
games;



if(currentCategory !== "All"){


list =
games.filter(
g =>
g.category === currentCategory
);


}




list.forEach(game=>{


let card =
document.createElement("div");


card.className="card";



card.innerHTML=

`

<img class="icon"
src="${game.icon}"
onerror="this.style.display='none'"/>

<h2>
${game.name}
</h2>

<p>
${game.description}
</p>

<button class="play">
Play
</button>

`;



card.querySelector(".play")
.onclick=()=>{


fetch(game.url)

.then(r=>r.text())

.then(html=>{


const dataURL =

"data:text/html;charset=utf-8,"
+
encodeURIComponent(html);



window.open(dataURL);


});


};



box.appendChild(card);


});


}







document
.querySelectorAll(".category")
.forEach(button=>{


button.onclick=()=>{


document
.querySelectorAll(".category")
.forEach(
b=>b.classList.remove("active")
);



button.classList.add("active");



currentCategory =
button.dataset.category;



renderGames();


};


});







document
.getElementById("search")
.oninput=function(){


let query =
this.value.toLowerCase();



let filtered =
games.filter(
g=>
g.name
.toLowerCase()
.includes(query)
);



const old =
currentCategory;



currentCategory="All";



const box =
document.getElementById("games");


box.innerHTML="";



filtered.forEach(game=>{


let card =
document.createElement("div");


card.className="card";


card.innerHTML=

`

<img class="icon"
src="${game.icon}"/>

<h2>${game.name}</h2>

<p>${game.description}</p>

<button class="play">
Play
</button>

`;



card.querySelector(".play")
.onclick=()=>{


fetch(game.url)

.then(r=>r.text())

.then(html=>{


window.open(

"data:text/html;charset=utf-8,"
+
encodeURIComponent(html)

);


});


};



box.appendChild(card);


});



};





loadGames();
